/** Actual attached launcher animations, scoped media decoding and full/PiP playback. */
public final class MediaSmoke {
    private final Instrumentation i;private final Context c;private final AppWidgetHost host;private final BiConsumer<Boolean,String> check;private final List<Integer> ids=new ArrayList<>();private final List<Uri> media=new ArrayList<>();private Activity display,player;
    private MediaSmoke(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check){this.i=i;this.c=c;this.host=host;this.check=check;}
    public static void run(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check)throws Exception{new MediaSmoke(i,c,host,check).run();}
    private void main(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();i.runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());i.waitForIdleSync();}
    private void waitFor(BooleanSupplier condition,String message)throws Exception{long until=SystemClock.elapsedRealtime()+7000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<until)Thread.sleep(70);check.accept(condition.getAsBoolean(),message);}
    private int bind(String kind,JSONObject config){int id=host.allocateAppWidgetId();ids.add(id);check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(id,new ComponentName(c,Widgets.provider(kind))),"Media provider binds: "+kind);Store.config(c,id,config);Widgets.update(c,id,kind);return id;}
    private View render(String kind,JSONObject config,int height){View view=Widgets.render(c,-1,kind,config,false,false).apply(c,new FrameLayout(c));view.measure(View.MeasureSpec.makeMeasureSpec(Ui.dp(c,320),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(Ui.dp(c,height),View.MeasureSpec.EXACTLY));view.layout(0,0,view.getMeasuredWidth(),view.getMeasuredHeight());return view;}
    private void click(int id,int target){main(()->host.createView(c,id,AppWidgetManager.getInstance(c).getAppWidgetInfo(id)).findViewById(target).performClick());SystemClock.sleep(130);i.waitForIdleSync();}
    private static TextView text(View root,String value){if(root instanceof TextView t&&value.contentEquals(t.getText()))return t;if(root instanceof ViewGroup g)for(int n=0;n<g.getChildCount();n++){TextView found=text(g.getChildAt(n),value);if(found!=null)return found;}return null;}
    private Uri image(int color)throws Exception{ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"nook-motion-test-"+color+".png");values.put(MediaStore.Images.Media.MIME_TYPE,"image/png");Uri uri=c.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);media.add(uri);Bitmap b=Bitmap.createBitmap(320,180,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(color);Paint p=new Paint(3);p.setColor(Color.WHITE);canvas.drawCircle(100,90,40,p);try(OutputStream out=c.getContentResolver().openOutputStream(uri)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();return uri;}
    private void attach(View view){FrameLayout panel=new FrameLayout(display);panel.setBackgroundColor(Ui.BG);FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(Ui.dp(c,340),Ui.dp(c,280),Gravity.CENTER);panel.addView(view,params);display.setContentView(panel);}
    private void shot(String name)throws Exception{Thread.sleep(350);Bitmap b=i.getUiAutomation().takeScreenshot();File folder=new File(c.getFilesDir(),"screenshots");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    private void run()throws Exception{
        JSONObject clip=null;
        try{
            display=i.startActivitySync(new Intent(c,WidgetConfigActivity.class).putExtra("kind","animation").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();
            main(()->{for(String kind:new String[]{"animation","slideshow","video"})for(int design=0;design<8;design++)for(int surface=0;surface<4;surface++)for(int height:new int[]{180,280})try{JSONObject config=Widgets.defaults(kind);WidgetDesign.select(config,design);config.put("style",surface).put("_height",height);View view=render(kind,config,height);View stage=view.findViewById(com.nook.widgets.R.id.media_stage),button=view.findViewById(com.nook.widgets.R.id.widget_action0);check.accept(stage.getHeight()>Ui.dp(c,12),"Every media design has visible image space: "+kind+" design="+design+" height="+height+" stage="+stage.getHeight());Rect bounds=new Rect();button.getDrawingRect(bounds);((ViewGroup)view).offsetDescendantRectToMyCoords(button,bounds);check.accept(bounds.bottom<=view.getHeight(),"Media controls fit at "+height+"dp");}catch(Exception e){throw new RuntimeException(kind+" design="+design+" surface="+surface,e);}});
            JSONObject animation=Widgets.defaults("animation");WidgetDesign.select(animation,2);int animated=bind("animation",animation);AtomicReference<ViewFlipper> flipper=new AtomicReference<>();main(()->{View view=host.createView(c,animated,AppWidgetManager.getInstance(c).getAppWidgetInfo(animated));attach(view);flipper.set(view.findViewById(com.nook.widgets.R.id.motion_flipper));check.accept(flipper.get()!=null&&flipper.get().getChildCount()==16,"Animated widget contains real native frame views");});int initial=flipper.get().getDisplayedChild();Thread.sleep(470);check.accept(flipper.get().isFlipping()&&flipper.get().getDisplayedChild()!=initial,"Attached native widget actually advances its animation");shot("animated-widget");click(animated,com.nook.widgets.R.id.widget_action0);check.accept(Store.config(c,animated).optBoolean("motionPaused"),"Actual Pause action persists");main(()->{View still=host.createView(c,animated,AppWidgetManager.getInstance(c).getAppWidgetInfo(animated));check.accept(still.findViewById(com.nook.widgets.R.id.motion_flipper)==null,"Paused widget removes the running animation view");});click(animated,com.nook.widgets.R.id.widget_action0);check.accept(!Store.config(c,animated).optBoolean("motionPaused",true),"Resume action restores motion");click(animated,com.nook.widgets.R.id.widget_action1);check.accept(Store.config(c,animated).optInt("variant")==1,"Change action selects another animation");
            Uri first=image(0xff236c85),second=image(0xffac674e);JSONObject slides=Widgets.defaults("slideshow");slides.put("slideUris",new JSONArray().put(first).put(second)).put("slideSeconds",2);int slideshow=bind("slideshow",slides);main(()->{View view=host.createView(c,slideshow,AppWidgetManager.getInstance(c).getAppWidgetInfo(slideshow));attach(view);flipper.set(view.findViewById(com.nook.widgets.R.id.motion_flipper));check.accept(flipper.get().getChildCount()==2&&flipper.get().getInAnimation()!=null,"Chosen photos use an actual fading ViewFlipper");});initial=flipper.get().getDisplayedChild();Thread.sleep(2250);check.accept(flipper.get().getDisplayedChild()!=initial,"Photo slideshow advances while attached");shot("slideshow-widget");click(slideshow,com.nook.widgets.R.id.widget_action0);click(slideshow,com.nook.widgets.R.id.widget_action1);check.accept(Store.config(c,slideshow).optBoolean("motionPaused")&&Store.config(c,slideshow).optInt("slideIndex")==1,"Paused slideshow can move to the next chosen photo");
            File encoded=new File(c.getCacheDir(),"nook-motion-test.mp4");encode(encoded);File samples=new File(c.getFilesDir(),"screenshots");samples.mkdirs();java.nio.file.Files.copy(encoded.toPath(),new File(samples,"sample-motion.mp4").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Nook sample motion.mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");Uri video=c.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);media.add(video);try(InputStream in=new FileInputStream(encoded);OutputStream out=c.getContentResolver().openOutputStream(video)){in.transferTo(out);}encoded.delete();clip=Widgets.defaults("video");clip.put("videoUri",video).put("videoName","Generated sample video").put("clipLength",2);JSONObject info=MediaData.prepare(c,clip,null);check.accept(info.optInt("count")>=8&&info.optLong("duration")>=1900,"Android decodes a real generated MP4 into a bounded preview");Bitmap frame0=MediaData.frame(c,clip,info,0),frameLast=MediaData.frame(c,clip,info,info.optInt("count")-1);check.accept(frame0!=null&&frameLast!=null&&frame0.getPixel(80,45)!=frameLast.getPixel(80,45),"Video preview contains changing source frames");frame0.recycle();frameLast.recycle();int videoId=bind("video",clip);JSONObject videoConfig=clip;main(()->{View view=host.createView(c,videoId,AppWidgetManager.getInstance(c).getAppWidgetInfo(videoId));attach(view);check.accept(view.findViewById(com.nook.widgets.R.id.video_flipper)!=null,"Video widget uses the full-source frame service");});shot("video-widget");
            JSONObject poster=new JSONObject(clip.toString()).put("variant",1);main(()->{View view=render("video",poster,250);check.accept(view.findViewById(com.nook.widgets.R.id.motion_flipper)==null,"Poster mode has no animation timer");});JSONObject before=new JSONObject(clip.toString());main(()->check.accept(!MediaOptions.picked(display,videoConfig,70,Activity.RESULT_CANCELED,null)&&before.toString().equals(videoConfig.toString()),"Canceling media selection preserves the chosen video"));
            player=i.startActivitySync(new Intent(c,VideoPlayerActivity.class).putExtra("widget",videoId).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check.accept(player!=null,"Optional native player opens explicitly");VideoView playback=player.findViewById(com.nook.widgets.R.id.video_player);waitFor(playback::isPlaying,"Selected local video plays through Android's decoder");int start=playback.getCurrentPosition();waitFor(()->playback.getCurrentPosition()!=start,"Full video playback position advances");shot("video-player");if(c.getPackageManager().hasSystemFeature(PackageManager.FEATURE_PICTURE_IN_PICTURE)){main(()->((VideoPlayerActivity)player).floatVideo());waitFor(player::isInPictureInPictureMode,"Real playback enters Android picture-in-picture");check.accept(playback.isPlaying(),"Video continues playing in the floating window");shot("video-floating");}main(player::finish);player=null;
            JSONObject hub=Widgets.defaults("universal");hub.put("page","video");UniversalWidget.pageSettings(hub,"video").put("videoUri",video).put("clipLength",2);int universal=bind("universal",hub);main(()->{View view=host.createView(c,universal,AppWidgetManager.getInstance(c).getAppWidgetInfo(universal));check.accept(view.findViewById(com.nook.widgets.R.id.video_flipper)!=null&&view.findViewById(com.nook.widgets.R.id.hub_next).getVisibility()==View.VISIBLE,"Video works inside Universal with navigation retained");});
            JSONObject invalid=new JSONObject(clip.toString()).put("videoUri","https://example.com/video.mp4");boolean rejected=false;try{MediaData.prepare(c,invalid,null);}catch(Exception e){rejected=true;}check.accept(rejected,"Preview preparation accepts selected document URIs only");
        }finally{if(player!=null)main(player::finish);if(display!=null)main(display::finish);for(int id:ids){host.deleteAppWidgetId(id);Store.removeConfig(c,id);}for(Uri uri:media)if(uri!=null)c.getContentResolver().delete(uri,null,null);if(clip!=null){File folder=new File(new File(c.getFilesDir(),"video_previews"),MediaData.key(clip));File[] files=folder.listFiles();if(files!=null)for(File file:files)file.delete();folder.delete();}}
    }
    private static void encode(File output)throws Exception{createSample(output,2,192,108,0);}
    public static void createSample(File output,int seconds,int width,int height,int rotation)throws Exception{
        MediaFormat format=MediaFormat.createVideoFormat("video/avc",width,height);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420SemiPlanar);format.setInteger(MediaFormat.KEY_BIT_RATE,180000);format.setInteger(MediaFormat.KEY_FRAME_RATE,15);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);MediaCodec codec=MediaCodec.createEncoderByType("video/avc");MediaMuxer muxer=new MediaMuxer(output.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);muxer.setOrientationHint(rotation);boolean muxing=false;try{codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();int frame=0,track=-1;boolean sentEnd=false,finished=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long deadline=SystemClock.elapsedRealtime()+15000;while(!finished&&SystemClock.elapsedRealtime()<deadline){if(!sentEnd){int input=codec.dequeueInputBuffer(10000);if(input>=0){if(frame<seconds*15){ByteBuffer bytes=codec.getInputBuffer(input);bytes.clear();int orbitX=width/2+(int)(Math.cos(frame*Math.PI/15)*58),orbitY=height/2+(int)(Math.sin(frame*Math.PI/15)*27);for(int y=0;y<height;y++)for(int x=0;x<width;x++){boolean orb=(x-orbitX)*(x-orbitX)+(y-orbitY)*(y-orbitY)<196;bytes.put((byte)(orb?220:35+x/4+y/5+frame));}for(int y=0;y<height/2;y++)for(int x=0;x<width/2;x++){boolean orb=(x*2-orbitX)*(x*2-orbitX)+(y*2-orbitY)*(y*2-orbitY)<196;bytes.put((byte)(orb?128:165-y));bytes.put((byte)(orb?128:95+x/3));}codec.queueInputBuffer(input,0,width*height*3/2,frame*1000000L/15,0);frame++;}else{codec.queueInputBuffer(input,0,0,seconds*1000000L,MediaCodec.BUFFER_FLAG_END_OF_STREAM);sentEnd=true;}}}int index=codec.dequeueOutputBuffer(info,10000);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=muxer.addTrack(codec.getOutputFormat());muxer.start();muxing=true;}else if(index>=0){ByteBuffer bytes=codec.getOutputBuffer(index);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0&&muxing){bytes.position(info.offset);bytes.limit(info.offset+info.size);muxer.writeSampleData(track,bytes,info);}finished=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(index,false);}}if(!finished)throw new IOException("Test video encoder timed out");}finally{try{codec.stop();}catch(Exception ignored){}codec.release();if(muxing)muxer.stop();muxer.release();}
    }
}
